import React, { useState } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Navbar from './Components/Navbar/Navbar';
import Hero from './Components/Hero/Hero'; 
import Footer from './Components/Footer/Footer';
import Home from './Pages/Home';
import LoginSignup from './Pages/LoginSignup';
import Products from './Pages/Products';
import About from './Pages/About';
import Contact from './Pages/Contact';
import Cart from './Pages/Cart';
import AdminDashboard from './Pages/AdminDashboard';
import ProtectedRoute from './Components/ProtectedRoute';
import SellerDashboard from './Pages/SellerDashboard';
import AddProductPage from './Pages/AddProductPage';
import Orders from './Pages/Orders';

function StoreLayout() {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false); // Default closed or open as an overlay

  return (
    <div style={{ display: 'flex', flexDirection: 'column', width: '100%', minHeight: '100vh', margin: 0, padding: 0, backgroundColor: '#f8f9fc', position: 'relative' }}>
      <style>{`
        body, html {
          margin: 0 !important;
          padding: 0 !important;
          overflow-x: hidden !important;
        }
      `}</style>

      {/* Sidebar Navigation as a Floating Overlay */}
      <div style={{ 
        width: '250px', 
        height: '100vh', 
        position: 'fixed', 
        top: '0', 
        left: isSidebarOpen ? '0' : '-250px', // Slides in and out smoothly
        zIndex: 2000,
        backgroundColor: '#ffffff',
        boxShadow: '4px 0 15px rgba(0,0,0,0.1)',
        transition: 'left 0.3s ease',
        overflowY: 'auto'
      }}>
        <Navbar />
      </div>

      {/* Backdrop overlay when sidebar is open */}
      {isSidebarOpen && (
        <div 
          onClick={() => setIsSidebarOpen(false)}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100vw',
            height: '100vh',
            backgroundColor: 'rgba(0,0,0,0.3)',
            zIndex: 1500
          }}
        />
      )}

      {/* Main Content Area spanning full width for true screen centering */}
      <div style={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: '100vh', width: '100%' }}>

        <Hero onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} />

        <main style={{ 
          flex: 1, 
          padding: '40px 20px', 
          boxSizing: 'border-box', 
          width: '100%', 
          display: 'flex', 
          flexDirection: 'column', 
          alignItems: 'center' // True horizontal centering on the screen
        }}>
          <div style={{ width: '100%', maxWidth: '1200px' }}>
            <Routes>
              <Route path='/' element={<Home />} />
              <Route path='/products' element={<Products />} />
              <Route path='/about' element={<About />} />
              <Route path='/contact' element={<Contact />} />
              <Route path='/login' element={<LoginSignup />} />
              <Route path='/cart' element={<Cart />} />
              <Route path='/orders' element={<Orders />} />
            </Routes>
          </div>
        </main>

        <Footer />
      </div>
    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/seller/*" element={<SellerDashboard />} />
        <Route path="/seller" element={<SellerDashboard />} />
        <Route path="/seller/add-product" element={<AddProductPage />} />
        <Route 
          path="/admin" 
          element={
            <ProtectedRoute adminOnly={true}>
              <AdminDashboard />
            </ProtectedRoute>
          } 
        />
        <Route path="/*" element={<StoreLayout />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
